--
-- Triggers `cm_emergency_cases`
--
DELIMITER $$
CREATE TRIGGER `tr_emergency_case_close` BEFORE UPDATE ON `cm_emergency_cases` FOR EACH ROW BEGIN
    IF NEW.case_status = 'Closed' AND OLD.case_status != 'Closed' THEN
        SET NEW.updated_at = NOW();
    END IF;
END
$$
DELIMITER ;

