(1, 'risk_assessment_notification', 'risk_assessment_notification', 'subject', 1, 'Risk Assessment Notification: Workplace Accident - Critical', 'Active', '2026-08-26 07:50:07', '2026-08-26 07:50:07'),
(2, 'risk_assessment_notification', 'risk_assessment_notification', 'body', 2, 'Dear Iris Soriano,\n\nThis is a notification regarding a risk assessment requiring your attention:\n\nRisk Category: Workplace Accident\nSeverity: Critical\nDescription: Workplace accident reported requiring immediate safety review.\nMitigation Plan: Conduct workplace inspection and implement safety measures.\n\nPlease review the details and take the necessary action at your earliest convenience. If you have any questions or need assistance, feel free to reach out to the HR department.\n\nBest regards,\nHR Department', 'Active', '2026-08-26 07:50:07', '2026-08-26 07:50:07');

