INSERT INTO `lc_incident_report` (`id`, `incident_id`, `incident_type`, `type`, `severity`, `status`, `requires_corrective_action`, `incident_date`, `incident_time`, `location`, `title`, `description`, `reporter_name`, `reporter_department`, `assigned_to`, `assigned_name`, `created_at`, `updated_at`) VALUES
(1, 'IR-2026-0001', 'Workplace Accident', 'Slip or Fall', 'high', 'investigation', 0, '2026-08-15', '09:30:00', 'Main Corridor, 2nd Floor', 'Employee Slip Near Wet Floor Area', 'An employee slipped near the main corridor where a water leak from the ceiling was present. The area was not cordoned off. The employee sustained minor bruises on the right arm and was given first aid at the clinic.', 'Maria Santos', 'ADMIN STAFF', 1, 'Ronaldo Raymundo', '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(2, 'IR-2026-0002', 'Health Incident', 'Fever', 'medium', 'submitted', 0, '2026-08-14', '14:15:00', 'Faculty Room, Building B', 'Teacher Reported High Fever and Fatigue', 'A faculty member reported experiencing high fever (38.9°C), chills, and body fatigue during class hours. The employee was sent home and advised to seek medical consultation. The clinic is monitoring the case.', 'Juan Dela Cruz', 'INSTRUCTORS', NULL, NULL, '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(3, 'IR-2026-0003', 'Medical Emergency', 'Cardiac-Related Emergency', 'critical', 'closed', 0, '2026-08-10', '11:45:00', 'Computer Laboratory, 3rd Floor', 'Staff Chest Pain During Work Hours', 'An administrative staff member experienced sudden chest pain and shortness of breath while working at the computer laboratory. Emergency protocol was activated, ambulance was called, and the employee was transported to the nearest hospital.', 'Roberto Albert', 'IT DEPARTMENT', 3, 'Erwin De Guzman', '2026-08-16 13:07:46', '2026-08-25 17:16:20'),
(4, 'IR-2026-0004', 'Occupational Injury', 'Minor Cut', 'low', 'resolved', 0, '2026-08-12', '10:20:00', 'Printing Room, Admin Building', 'Paper Cut Incident While Handling Documents', 'An employee sustained a minor paper cut on the left index finger while handling bulk printed documents. The wound was cleaned and bandaged at the clinic. No lost-time injury recorded.', 'Althea Santos', 'ADMIN STAFF', NULL, NULL, '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(5, 'IR-2026-0005', 'Environmental & Safety Hazard', 'Chemical Spill (Laboratory)', 'high', 'under_review', 0, '2026-08-13', '16:00:00', 'Science Laboratory, Room 204', 'Acid Spill in Chemistry Laboratory', 'A small amount of hydrochloric acid spilled during a student laboratory session. The area was evacuated, spill kit was used, and the laboratory was ventilated. No injuries reported. Safety protocols are being reviewed.', 'Elena Ocampo', 'PSYCHOLOGY DEPARTMENT', 1, 'Ronaldo Raymundo', '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(6, 'IR-2026-0006', 'Exposure Incident', 'Biological Exposure', 'high', 'investigation', 0, '2026-08-11', '08:45:00', 'Biology Laboratory, Room 102', 'Student and Staff Exposure to Biological Sample', 'A laboratory assistant was accidentally exposed to a biological sample when a test tube slipped. The assistant was wearing PPE but reported the incident for documentation. Post-exposure prophylaxis was recommended by the clinic.', 'Caleb Santos', 'INSTRUCTORS', 3, 'Erwin De Guzman', '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(7, 'IR-2026-0007', 'Near Miss', 'Laboratory Near Miss', 'medium', 'closed', 0, '2026-08-09', '13:30:00', 'Chemistry Laboratory, Room 204', ' Bunsen Burner Left Unattended', 'A Bunsen burner was left unattended with the gas valve partially open. A passing instructor noticed the flame and immediately turned it off. No fire or injury occurred. The lab session was suspended pending safety review.', 'David Aquino', 'INSTRUCTORS', NULL, NULL, '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(8, 'IR-2026-0008', 'Return-to-Work Monitoring', 'Fit-to-Work Clearance', 'low', 'submitted', 0, '2026-08-16', '07:30:00', 'Clinic, Ground Floor', 'Employee Return After Medical Leave', 'An employee who was on medical leave for hypertension management has submitted a fit-to-work clearance from the company physician. The clearance indicates the employee may return to regular duties with monthly monitoring.', 'Fiona Ramos', 'ADMIN STAFF', NULL, NULL, '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(9, 'IR-2026-0009', 'Workplace Accident', 'Falling Object Injury', 'medium', 'submitted', 0, '2026-08-14', '11:10:00', 'Storage Area, Basement', 'Box Fell from Shelf Causing Head Injury', 'A storage box containing office supplies fell from an overhead shelf and struck an employee on the forehead. The employee was given first aid and observed at the clinic. The storage area was inspected for proper shelving arrangement.', 'Gabriel Gonzales', 'ADMIN STAFF', 1, 'Ronaldo Raymundo', '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(10, 'IR-2026-0010', 'Health Incident', 'Infectious Disease Symptoms', 'medium', 'under_review', 0, '2026-08-13', '15:45:00', 'Faculty Lounge, 2nd Floor', 'Multiple Faculty Members Reported Cough and Cold Symptoms', 'Three faculty members reported experiencing persistent cough, sore throat, and mild fever over a three-day period. The clinic has documented the cases and recommended temporary remote work arrangements and increased sanitation in shared areas.', 'Hugo Villanueva', 'INSTRUCTORS', 3, 'Erwin De Guzman', '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(11, 'IR-2026-0011', 'Medical Emergency', 'Severe Allergic Reaction', 'high', 'investigation', 0, '2026-08-12', '12:30:00', 'Cafeteria, Ground Floor', 'Staff Anaphylaxis After Lunch', 'A staff member experienced anaphylaxis approximately 15 minutes after eating lunch in the cafeteria. The individual reported difficulty breathing and swelling of the face. Epinephrine was administered at the clinic and emergency services were contacted.', 'Ian Fernandez', 'ADMIN STAFF', 3, 'Erwin De Guzman', '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(12, 'IR-2026-0012', 'Occupational Injury', 'Back Injury', 'medium', 'investigation', 0, '2026-08-10', '08:00:00', 'Records Section, 2nd Floor', 'Employee Back Strain from Lifting Heavy Files', 'An employee reported severe back pain after lifting a heavy box of archived records without mechanical assistance. The employee was referred to an orthopedist. The case has been escalated for ergonomic assessment and provision of lifting equipment.', 'Jacob Lopez', 'ADMIN STAFF', 1, 'Ronaldo Raymundo', '2026-08-16 13:07:46', '2026-08-25 17:17:03'),
(13, 'IR-2026-0013', 'Environmental & Safety Hazard', 'Electrical Hazard', 'critical', 'resolved', 0, '2026-08-15', '10:00:00', 'Server Room, IT Department', 'Exposed Electrical Wiring Near Server Racks', 'Maintenance staff discovered exposed electrical wiring near the server racks in the IT department. The area was immediately isolated and power was disconnected. An electrician has been contracted to repair the wiring before operations resume.', 'Rainiel Quebada', 'IT DEPARTMENT', 3, 'Erwin De Guzman', '2026-08-16 13:07:46', '2026-08-22 06:28:45'),
(14, 'IR-2026-0014', 'Exposure Incident', 'Chemical Exposure', 'high', 'investigation', 0, '2026-08-11', '14:20:00', 'Printing Room, Admin Building', 'Toner Exposure During Printer Maintenance', 'A maintenance worker was exposed to printer toner dust while servicing a large-format printer without a mask. The worker reported respiratory irritation and eye redness. The incident was reported to the safety officer and medical evaluation was conducted.', 'Karl Solis', 'ADMIN STAFF', 3, 'Erwin De Guzman', '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(15, 'IR-2026-0015', 'Near Miss', 'Equipment Malfunction', 'low', 'closed', 0, '2026-08-08', '09:00:00', 'Auditorium, 2nd Floor', 'Projector Mount Detached During Presentation', 'A projector mount detached from the ceiling during a presentation, falling approximately 1.5 meters from the ceiling. No one was injured, but the audience was startled. The mounting hardware was inspected and replaced. AV equipment maintenance schedule has been updated.', 'Geoffrey Balansag', 'INSTRUCTORS', NULL, NULL, '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(16, 'IR-2026-0016', 'Return-to-Work Monitoring', 'Return After Workplace Injury', 'medium', 'submitted', 0, '2026-08-16', '08:15:00', 'Clinic, Ground Floor', 'Employee Return After Back Injury Recovery', 'An employee who sustained a back injury on August 10, 2026, has submitted a return-to-work clearance. The physician has recommended light duties for two weeks with restrictions on lifting objects heavier than 5 kg.', 'Johnloyd Reyes', 'ADMIN STAFF', 1, 'Ronaldo Raymundo', '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(17, 'IR-2026-0017', 'Workplace Accident', 'Stairway Accident', 'high', 'escalated', 0, '2026-08-09', '17:30:00', 'Main Staircase, Building A', 'Employee Fell Down Stairs Due to Poor Lighting', 'An employee fell down three steps on the main staircase due to a non-functioning light fixture. The employee sustained a sprained ankle and bruising on the left thigh. The staircase lighting was repaired within two hours. The case has been escalated for facilities review.', 'Alexis Cueto', 'ADMIN STAFF', 3, 'Erwin De Guzman', '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(18, 'IR-2026-0018', 'Health Incident', 'Hypertension', 'low', 'resolved', 0, '2026-08-07', '08:45:00', 'Clinic, Ground Floor', 'Staff Member Elevated Blood Pressure Detected', 'Routine health screening at the clinic detected elevated blood pressure (150/95 mmHg) in a staff member. The individual was advised to reduce stress, monitor blood pressure daily, and schedule a follow-up with a physician. The case is considered resolved with ongoing monitoring.', 'Jayson Paigma', 'IT DEPARTMENT', NULL, NULL, '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(19, 'IR-2026-0019', 'Medical Emergency', 'Fracture', 'high', 'under_review', 0, '2026-08-14', '16:20:00', 'Parking Area, Building C', 'Student Fracture During Physical Education Class', 'A student fell during a physical education activity and sustained a fracture in the right forearm. The incident was reported by the PE instructor. The student was transported to the hospital. The case is under review for safety assessment of the activity area.', 'Zenith Tolentino', 'INSTRUCTORS', 3, 'Erwin De Guzman', '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(20, 'IR-2026-0020', 'Occupational Injury', 'Eye Irritation', 'low', 'closed', 0, '2026-08-06', '10:45:00', 'Science Laboratory, Room 204', 'Chemical Splash in Eye During Experiment', 'A student accidentally splashed a small amount of sulfuric acid into their right eye during a laboratory experiment. The eyewash station was used immediately and the student was referred to the clinic. The eye was irrigated and the student was sent home with an eye patch and medication.', 'Lumina Tolentino', 'INSTRUCTORS', NULL, NULL, '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(21, 'IR-2026-0021', 'Workplace Accident', 'Office Injury', 'medium', 'submitted', 0, '2026-08-16', '11:00:00', 'Human Resources Office, 2nd Floor', 'Employee Struck by Filing Cabinet Door', 'A filing cabinet door detached from its hinge and struck an employee on the shoulder. The employee reported pain and limited mobility. The cabinet was removed from service and maintenance was contacted. The incident is documented for follow-up.', 'Iris Soriano', 'ADMIN STAFF', 1, 'Ronaldo Raymundo', '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(22, 'IR-2026-0022', 'Health Incident', 'Anxiety/Panic Episode', 'medium', 'under_review', 0, '2026-08-15', '13:00:00', 'Guidance Office, 1st Floor', 'Student Panic Attack During Examination', 'A student experienced a panic attack during a midterm examination. The proctor immediately contacted the clinic and guidance office. The student was assisted to the clinic for stabilization and was later accompanied home by a guardian. The incident is under review for wellness program recommendations.', 'Gia Valdez', 'INSTRUCTORS', 3, 'Erwin De Guzman', '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(23, 'IR-2026-0023', 'Medical Emergency', 'Breathing Difficulty', 'high', 'investigation', 0, '2026-08-13', '09:15:00', 'Classroom 301, Building B', 'Student Asthma Attack During Class', 'A student experienced an acute asthma attack during a morning class. The instructor administered the students rescue inhaler and contacted the clinic. The student was stabilized at the clinic and parents were notified. The case is under investigation for classroom air quality assessment.', 'Aaron Pascual', 'INSTRUCTORS', 3, 'Erwin De Guzman', '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(24, 'IR-2026-0024', 'Environmental & Safety Hazard', 'Fire Safety Concern', 'critical', 'resolved', 0, '2026-08-16', '15:30:00', 'Cafeteria Kitchen, Ground Floor', 'Grease Fire in Cafeteria Kitchen', 'A grease fire started in the cafeteria kitchen when oil overheated on the stove. The fire suppression system activated and the local fire department was contacted. No injuries occurred, but the kitchen sustained minor damage. The incident is under investigation for fire safety compliance.', 'Vibe Mercado', 'ADMIN STAFF', 1, 'Ronaldo Raymundo', '2026-08-16 13:07:46', '2026-08-26 22:46:01'),
(25, 'IR-2026-0025', 'Exposure Incident', 'Smoke Inhalation', 'high', 'resolved', 0, '2026-08-16', '15:45:00', 'Cafeteria, Ground Floor', 'Staff Smoke Inhalation During Cafeteria Fire', 'A kitchen staff member inhaled smoke during the grease fire incident and reported coughing and breathing difficulty. The staff member was given oxygen at the clinic and monitored for two hours before being cleared. The case is under investigation alongside the fire incident.', 'Diana Mercado', 'ADMIN STAFF', 3, 'Erwin De Guzman', '2026-08-16 13:07:46', '2026-08-26 06:54:33'),
(26, 'IR-2026-0026', 'Near Miss', 'Vehicle Near Miss', 'medium', 'closed', 0, '2026-08-08', '07:45:00', 'Main Parking Lot, Gate 2', 'Vehicle Almost Hit Pedestrian in Parking Lot', 'A vehicle exiting the main parking lot nearly struck a pedestrian crossing the access road. The driver applied brakes abruptly, avoiding collision. The security guard witnessed the incident. Speed bumps and signage have been recommended for the area.', 'Jhon Carlo Garcia', 'ADMIN STAFF', NULL, NULL, '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(27, 'IR-2026-0027', 'Return-to-Work Monitoring', 'Work Restrictions', 'low', 'submitted', 0, '2026-08-16', '10:30:00', 'Clinic, Ground Floor', 'Employee Return With Temporary Work Restrictions', 'An employee recovering from a workplace injury has returned to work with temporary restrictions: no prolonged standing, no lifting over 10 kg, and mandatory rest breaks every two hours. The restrictions will be reviewed after two weeks.', 'Russel Cabrido', 'ADMIN STAFF', 1, 'Ronaldo Raymundo', '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(28, 'IR-2026-0028', 'Workplace Accident', 'Laboratory Injury', 'medium', 'investigation', 0, '2026-08-11', '14:00:00', 'Computer Laboratory, 3rd Floor', 'Student Cut Finger on Damaged Keyboard Edge', 'A student sustained a deep cut on the left thumb when a damaged keyboard edge sliced the skin. The wound required sutures at the clinic. The computer laboratory equipment inspection was initiated. The incident is under investigation.', 'Jose Mari Malana', 'INSTRUCTORS', 3, 'Erwin De Guzman', '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(29, 'IR-2026-0029', 'Health Incident', 'Heat Exhaustion', 'medium', 'resolved', 0, '2026-08-07', '12:30:00', 'Sports Facility, Outdoor Court', 'Student Heat Exhaustion During PE Activity', 'A student showed signs of heat exhaustion (dizziness, nausea, excessive sweating) during an outdoor sports activity. The student was moved to a shaded area, hydrated, and cooled with wet cloths. The student recovered within an hour and was sent home with parental notification.', 'Russell Placer', 'INSTRUCTORS', NULL, NULL, '2026-08-16 13:07:46', '2026-08-16 13:07:46'),
(30, 'IR-2026-0030', 'Medical Emergency', 'Emergency Hospital Referral', 'high', 'escalated', 0, '2026-08-12', '22:00:00', 'Dormitory, Building D', 'Student Emergency Referral for Acute Appendicitis', 'A dormitory resident experienced severe abdominal pain and was assessed by the clinic physician as a probable appendicitis case. The student was immediately referred to the hospital for emergency surgery. The parents were notified. The case has been escalated for dormitory safety review.', 'Cheska Baustita', 'INSTRUCTORS', 3, 'Erwin De Guzman', '2026-08-16 13:07:46', '2026-08-16 13:07:46');

